import java.util.*;class GroundSmoothingTest{public static void main(String[]a){int n=256;var e=new EnvironmentMap(new float[n*n]);e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++)e.height[z*n+x]=102+Math.abs(x-80)*.18f;for(int z=0;z<n;z++)for(int x=76;x<=84;x++){int i=z*n+x;e.height[i]=96;e.water[i]=100;e.river[i]=1;}for(int z=90;z<160;z++)for(int x=100;x<130;x++)e.height[z*n+x]+=6;float[] water=e.water.clone(),distant=e.height.clone();long changes=GroundSmoothing.apply(e,n,n,62,160,()->false);float maximum=0;for(int z=95;z<155;z++)for(int x=95;x<135;x++){int i=z*n+x;maximum=Math.max(maximum,Math.max(Math.abs(e.height[i]-e.height[i+1]),Math.abs(e.height[i]-e.height[i+n])));}if(changes==0||maximum>1||!Arrays.equals(water,e.water)||e.height[128*n+80]!=96||e.height[128*n+255]!=distant[128*n+255])throw new AssertionError("Smoothing failed: "+maximum);System.out.println("PASS: abrupt dirt ledge removed, gentle slopes retained, water/riverbed/distant terrain unchanged; max local step="+maximum);}}
